'use strict';
(()=>{
 const $=id=>document.getElementById(id);
 const definitions=[['studio-season',['Closed · winter','Open · summer']],['sauna-size',['S','M','L']],['sauna-storage',['No','Yes']],['sauna-roof',['Flat','Single slope','Gable']],['terrace-depth',['1200']],['window-width',['580','880','1180']]];
 for(const [id,labels]of definitions){
  const el=$(id),check=el.type==='checkbox',row=document.createElement('div');row.className='choice-row'+(id==='sauna-roof'?' roof':'');row.role='radiogroup';row.setAttribute('aria-labelledby',id+'-label');const label=document.querySelector('label[for="'+id+'"]')||el.closest('label');label.id=id+'-label';if(check){label.after(el);label.classList.remove('toggle-line');}el.classList.add('native-choice');el.tabIndex=-1;el.setAttribute('aria-hidden','true');el.after(row);
  const sync=()=>{for(const [i,b]of [...row.children].entries()){const on=check?el.checked===Boolean(i):el.selectedIndex===i;b.setAttribute('aria-checked',on);b.tabIndex=on?0:-1;}};
  labels.forEach((text,i)=>{const b=document.createElement('button');b.type='button';b.role='radio';b.textContent=text;b.dataset.value=check?String(Boolean(i)):el.options[i].value;b.onclick=()=>{if(check)el.checked=Boolean(i);else el.selectedIndex=i;sync();el.dispatchEvent(new Event('change',{bubbles:true}));};b.onkeydown=e=>{if(!['ArrowRight','ArrowLeft','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?labels.length-1:(i+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)+labels.length)%labels.length;row.children[j].click();row.children[j].focus();};row.append(b);});sync();el.addEventListener('change',sync);
 }
 $('facade').classList.add('native-choice');$('facade').tabIndex=-1;const sample=document.createElement('div');sample.className='material-sample';sample.textContent='Vertical timber';$('facade').after(sample);
 const appearance=document.createElement('div');appearance.className='appearance';appearance.innerHTML='<label for="appearance">Appearance</label><select id="appearance"><option value="arctic">White model</option><option value="materials">Materials</option></select>';document.querySelector('.view-switch').before(appearance);
 const product=document.createElement('section');product.id='customer-product';product.className='customer-page';product.hidden=true;product.innerHTML='<p>OBTP / MODULAR SPACES</p><h1>Room for what matters.</h1><p class="customer-note">We develop compact timber spaces for work, creativity and sauna rituals. One modular system, thoughtful layouts and a close connection to the outdoors.</p><button id="product-config">Explore the configurator</button><figure class="home-hero"><img src="images/studio-01.webp" width="2048" height="1228" fetchpriority="high" alt="Timber studio among trees, viewed from the terrace"></figure><div class="home-intro"><h2>A simple structure. Your own rhythm.</h2><p>Choose a studio for focused work or a sauna for a slower moment. Explore the size, layout and details in the configurator.</p></div><div class="photo-grid"><figure><img src="images/studio-02.webp" width="2016" height="1234" loading="lazy" alt="Front elevation of the timber studio"></figure><figure><img src="images/studio-03.webp" width="1981" height="1242" loading="lazy" alt="Side view of the timber studio in a woodland setting"></figure></div><p class="render-caption">Architectural visualisations. Final details follow the selected configuration.</p>' ;document.body.append(product);
 const drawings=document.createElement('section');drawings.id='customer-drawings';drawings.className='customer-page';drawings.hidden=true;drawings.innerHTML='<h1>Your drawings.</h1><p>Plan, two sections, window schedule and reserved construction details.</p><div class="drawing-actions"><a id="pdf-download" download>Download PDF</a></div><p id="drawing-selection"></p><p>A3 · plan and sections 1:25 · window 1:10 · vertical window details 1:2.</p>';document.body.append(drawings);
 window.OBTPCustomerView=(value)=>{const section=value===true?'info':value===false?'config':value;for(const [id,key]of [['configurator','config'],['customer-information','info'],['customer-product','product'],['customer-drawings','drawings']])$(id).hidden=section!==key;window.OBTPConfigOverlay?.(false);$('mobile-config-toggle').hidden=section!=='config';window.scrollTo(0,0);if(section==='drawings')window.OBTPUpdatePDF?.();};$('product-config').onclick=()=>OBTPCustomerView('config');$('back-config').onclick=()=>OBTPCustomerView('config');
 window.OBTPUpdatePDF=()=>{const state=window.OBTPStudioV3;if(!state)return;const s=state.selection,key=`${s.program}-${s.size}-${s.storage?'storage':'open'}-r${s.roof}-t${s.terrace}-w${s.window}-f${s.facade}${s.program==='studio'&&s.season==='summer'?'-summer':''}`;const url='generated/'+key+'.pdf?build='+state.sourceRevision;$('pdf-download').href=url;$('pdf-download').download=key+'.pdf';$('drawing-selection').textContent=`${s.size.toUpperCase()} · ${s.window} × 1880 mm · PIHLA Varma Kiinteä`;};
 window.OBTPProgramRender=()=>{
  const studio=$('preset').value==='studio';
  document.querySelector('aside h1').textContent=studio?'Configure your studio.':'Configure your sauna.';
  document.querySelector('label[for="sauna-size"]').textContent=studio?'Studio size':'Sauna size';
  document.querySelector('label[for="sauna-storage"]')?.removeAttribute('data-unused');
  const storageLabel=$('sauna-storage-label');if(storageLabel)storageLabel.textContent=studio?'Storage shelves':'External storage + outdoor seat';
  const mark=document.querySelector('aside > p');if(mark)mark.textContent=studio?'OBTP / MODULAR STUDIO':'STUDIO V3 / CASSETTE 01';
 };
 const main=$('configurator'),panel=main.querySelector('aside'),preview=main.querySelector('section');
 panel.id='configuration-panel';
 const toggle=document.createElement('button');toggle.id='mobile-config-toggle';toggle.type='button';toggle.setAttribute('aria-controls',panel.id);toggle.setAttribute('aria-expanded','false');toggle.innerHTML='<span class="open-label">Configure</span><span class="close-label" hidden>Close configuration</span>';main.append(toggle);
 const backdrop=document.createElement('button');backdrop.id='config-backdrop';backdrop.type='button';backdrop.tabIndex=-1;backdrop.setAttribute('aria-label','Close configuration');backdrop.hidden=true;main.append(backdrop);
 const mobile=matchMedia('(max-width:850px)');
 window.OBTPConfigOverlay=open=>{open=Boolean(open&&mobile.matches);main.classList.toggle('config-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.querySelector('.open-label').hidden=open;toggle.querySelector('.close-label').hidden=!open;backdrop.hidden=!open;preview.inert=open;panel.inert=mobile.matches&&!open;if(open){panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Configuration');panel.setAttribute('aria-modal','true');const first=panel.querySelector('#preset')||panel.querySelector('.choice-row button[aria-checked="true"]');first?.focus();}else{panel.removeAttribute('role');panel.removeAttribute('aria-modal');}};
 toggle.onclick=()=>OBTPConfigOverlay(toggle.getAttribute('aria-expanded')!=='true');backdrop.onclick=()=>{OBTPConfigOverlay(false);toggle.focus();};
 document.addEventListener('keydown',e=>{if(!main.classList.contains('config-open'))return;if(e.key==='Escape'){OBTPConfigOverlay(false);toggle.focus();}if(e.key==='Tab'){const focusable=[...panel.querySelectorAll('button,a,select,input')].filter(x=>!x.disabled&&x.tabIndex>=0&&x.getClientRects().length&&!x.classList.contains('native-choice'));focusable.push(toggle);const i=focusable.indexOf(document.activeElement);e.preventDefault();focusable[(i+(e.shiftKey?-1:1)+focusable.length)%focusable.length]?.focus();}});
 mobile.addEventListener('change',()=>OBTPConfigOverlay(false));OBTPConfigOverlay(false);
})();
